import{_ as e,o as r,c as n,a0 as c}from"./chunks/framework.BGyYNsHo.js";const m=JSON.parse('{"title":"Geometría de la sección transversal","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/04-geometria-de-secciones.md","filePath":"es/explanation/hidraulica/04-geometria-de-secciones.md"}'),o={name:"es/explanation/hidraulica/04-geometria-de-secciones.md"};function s(i,a,t,l,d,u){return r(),n("div",null,[...a[0]||(a[0]=[c('<h1 id="geometria-de-la-seccion-transversal" tabindex="-1">Geometría de la sección transversal <a class="header-anchor" href="#geometria-de-la-seccion-transversal" aria-label="Permalink to &quot;Geometría de la sección transversal&quot;">​</a></h1><h2 id="las-cuatro-relaciones-geometricas" tabindex="-1">Las cuatro relaciones geométricas <a class="header-anchor" href="#las-cuatro-relaciones-geometricas" aria-label="Permalink to &quot;Las cuatro relaciones geométricas&quot;">​</a></h2><p>Para un conducto, el área hidráulica $A$, el espejo de agua (ancho superficial) $W$, el perímetro mojado $P_w$ y el radio hidráulico $R = A/P_w$ son funciones del tirante $y$. El motor precalcula, para cada forma, las cuatro relaciones fundamentales (<code>XSectKernels.hpp</code>, <code>xsect_tables.hpp</code>):</p><p>$$ \\begin{aligned} A &amp;= A(y), \\qquad W = W(y), \\qquad R = R(y), \\ S &amp;= S(A) = A,R^{2/3} \\quad \\text{(factor de sección, &quot;forma de capacidad de conducción&quot;),} \\end{aligned} $$</p><p>junto con sus inversas $y = y(A)$, $A = A(S)$ y la derivada $dS/dA$. Existen expresiones cerradas para las formas estándar (circular, circular llena, rectangular, trapezoidal, triangular, parabólica, potencia, huevo, herradura, gótica, canasta, etc.); las formas irregulares y personalizadas usan tablas (transectas) con interpolación lineal, y la inversa $A(S)$ se resuelve por iteración de Newton o inversión de tabla.</p><h2 id="manning-y-el-factor-de-seccion" tabindex="-1">Manning y el factor de sección <a class="header-anchor" href="#manning-y-el-factor-de-seccion" aria-label="Permalink to &quot;Manning y el factor de sección&quot;">​</a></h2><p>La ecuación de Manning en forma US es</p><p>$$Q = \\frac{1.486}{n},A,R^{2/3},\\sqrt{S_f} = \\beta,\\Psi(A),\\sqrt{S_f/S_0}, \\qquad \\Psi(A) = A,R^{2/3},$$</p><p>donde $S_f$ es la pendiente de fricción, $\\beta = (1.486/n)\\sqrt{S_0}$ y $\\Psi(A)$ es el factor de sección. Para muchas formas cerradas el factor de sección presenta un máximo bajo la profundidad total, de modo que el caudal máximo ocurre a un área menor que la de sección llena.</p>',9)])])}const $=e(o,[["render",s]]);export{m as __pageData,$ as default};
